import requestsimport osimport json from bs4 import BeautifulSoupfrom dotenv import load_dotenvfrom openai import OpenAIfrom config import model, linkSysPrompt# Headers for requestsheaders = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/117.0.0.0 Safari/537.36"}def loadAPIKey():    load_dotenv(override=True)    api_key = os.getenv('OPENAI_API_KEY')    if api_key and api_key.startswith('sk-proj-') and len(api_key)>10:        print("API key looks good so far")        return api_key    else:        print("There might be a problem with your API key? Please visit the troubleshooting notebook!")        return None# Initialize OpenAI apiKey = loadAPIKeyopenai = OpenAI(api_key=apiKey)class Website:        def __init__(self, url):        self.url = url        try:            response = requests.get(url, headers=headers, timeout=10)            response.raise_for_status()        except requests.exceptions.RequestException as e:            print(f"Failed to fetch {url}: {e}")            self.body = b""            self.title = f"Failed to load {url}"            self.text = ""            self.links = []            return                self.body = response.content        soup = BeautifulSoup(self.body, 'html.parser')        self.title = soup.title.string if soup.title else "No title found"        if soup.body:            for irrelevant in soup.body(["script", "style", "img", "input"]):                irrelevant.decompose()            self.text = soup.body.get_text(separator="\n", strip=True)        else:            self.text = ""        links = [link.get('href') for link in soup.find_all('a')]        self.links = [link for link in links if link]    def getContents(self):        return f"Webpage Title:\n{self.title}\nWebpage Contents:\n{self.text}\n\n"    def getLinksUserPrompt(website):    user_prompt = f'Here is the list of links on the website of {website.url} - '    user_prompt += "please decide which of these are relevant web links for a brochure about the company, respond with the full https URL in JSON format. Do not include Terms of Service, Privacy, email links.\n"    user_prompt += "Links (some might be relative links):\n"    user_prompt += "\n".join(website.links)    return user_promptdef getLinks(url):    website = Website(url)    response = openai.chat.completions.create(        model=model,        messages=[            {"role": "system", "content": linkSysPrompt},            {"role": "user", "content": getLinksUserPrompt(website)}      ],        response_format={"type": "json_object"}    )    result = response.choices[0].message.content    return json.loads(result)def getAllContent(url):    result = "Landing page:\n"    result += Website(url).getContents()    links = getLinks(url)    print("Found links:", links)    for link in links["links"]:        result += f"\n\n{link['type']}\n"        result += Website(link["url"]).getContents()    return result